add_filter( 'woocommerce_default_address_fields', 'perfectpixel_rename_state_label', 9999 );
add_filter( 'woocommerce_get_country_locale', 'perfectpixel_rename_state_label_locale', 9999 );

function perfectpixel_rename_state_label( $fields ) {
	if ( isset( $fields['state'] ) ) {
		$fields['state']['label'] = '{{state_label}}';
	}
	return $fields;
}

// Some countries define their own state label (e.g. "County"); override it too.
function perfectpixel_rename_state_label_locale( $locale ) {
	foreach ( $locale as $country => $fields ) {
		if ( isset( $fields['state']['label'] ) ) {
			$locale[ $country ]['state']['label'] = '{{state_label}}';
		}
	}
	return $locale;
}
